import pandas as pd

def clean(df):
    allowed_categories = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
    df["Category"] = df["Category"].str.strip()
    df = df[df["Category"].isin(allowed_categories)]

    allowed_regions = ["North", "South", "East", "West"]
    df["Region"] = df["Region"].str.strip()
    df = df[df["Region"].isin(allowed_regions)]

    df["Revenue"] = df["Quantity"] * df["Price"]
    return df

def answer(df):
    electronics = df[df["Category"] == "Electronics"]
    if electronics.empty:
        return {}
    grouped = electronics.groupby("Region")["Revenue"].sum()
    return grouped.to_dict()
